package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilderWithValueSeparatorTest {

    @BeforeEach
    public void beforeEach() throws Exception {
        invokeReset();
    }

    @AfterEach
    public void afterEach() throws Exception {
        invokeReset();
    }

    @Test
    public void testWithValueSeparatorSetsValueAndReturnsInstance() throws Exception {
        char sep = '=';
        OptionBuilder returned = OptionBuilder.withValueSeparator(sep);

        OptionBuilder instance = getInstanceViaReflection();
        assertSame(instance, returned, "withValueSeparator should return the singleton INSTANCE");
        assertEquals(sep, getValueSeparatorViaReflection(), "valueSeparator field should be set to provided char");
    }

    @Test
    public void testWithValueSeparatorUpdatesValueOnMultipleCalls() throws Exception {
        // first call
        OptionBuilder.withValueSeparator(':');
        assertEquals(':', getValueSeparatorViaReflection(), "valueSeparator should be ':' after first call");

        // second call with a different character
        OptionBuilder.withValueSeparator('\u0000');
        assertEquals('\u0000', getValueSeparatorViaReflection(), "valueSeparator should update to the new char");
    }

    @Test
    public void testReturnedInstanceIsAlwaysSameSingleton() throws Exception {
        OptionBuilder first = OptionBuilder.withValueSeparator('x');
        OptionBuilder second = OptionBuilder.withValueSeparator('y');

        assertSame(first, second, "Repeated calls should return the same singleton instance");
        // also verify the singleton matches the private INSTANCE field
        OptionBuilder instance = getInstanceViaReflection();
        assertSame(instance, first, "Returned instance should be the private INSTANCE singleton");
    }

    // --- Reflection helpers ---

    private static char getValueSeparatorViaReflection() throws Exception {
        Field f = OptionBuilder.class.getDeclaredField("valueSeparator");
        f.setAccessible(true);
        return f.getChar(null); // static field
    }

    private static OptionBuilder getInstanceViaReflection() throws Exception {
        Field f = OptionBuilder.class.getDeclaredField("INSTANCE");
        f.setAccessible(true);
        return (OptionBuilder) f.get(null);
    }

    private static void invokeReset() throws Exception {
        Method m = OptionBuilder.class.getDeclaredMethod("reset");
        m.setAccessible(true);
        m.invoke(null);
    }
}

